# In clap, to get "[=<VALUE>]" you need .num_args(0..=1) and .value_name plus default missing? But we already have that, yet ours still shows "[<...>]" not "[=<...>]"? Let's check.
# Our orig check shows "--respect-gitignore[=<RESPECT_GITIGNORE>]" exactly. Our cargo_test shows "--respect-gitignore [<RESPECT_GITIGNORE>]" with space. How to get =?
# Possibly clap 4.6 behavior for optional value with "=": need to set .num_args(0..=1) plus .last? Or set .value_terminator? Let's search memory: clap arg with optional value shows as "[=<VALUE>]" if you set .num_args(0..=1) and require_equals? Actually there is .require_equals?
# In docs, optional value with "=" syntax: Arg::new(...).long(...).value_name(...).num_args(0..=1).default_missing_value("true")
# That should produce "[=<VALUE>]" ? But we had that and got space version. Maybe need to enable require_equals false? Let's test variations.

cat <<'EOF' > src/main.rs
use clap::{Command, Arg};

fn main() {
    let cmd = Command::new("test")
        .arg(
            Arg::new("respect")
                .long("respect-gitignore")
                .value_name("RESPECT_GITIGNORE")
                .value_parser(["true","false"])
                .num_args(0..=1)
                .default_missing_value("true")
        );
    let m = cmd.clone().get_matches_from(vec!["test", "--help"]);
    // Actually we want help output
    let mut cmd2 = Command::new("test")
        .arg(
            Arg::new("respect")
                .long("respect-gitignore")
                .value_name("RESPECT_GITIGNORE")
                .value_parser(["true","false"])
                .num_args(0..=1)
                .default_missing_value("true")
                .help("Respect .gitignore files when scanning directories (does not apply to explicitly provided paths)")
        );
    cmd2.debug_assert();
    let mut buf = Vec::new();
    use clap::CommandFactory;
    use clap::Parser;
    // Use help printing
    let help = cmd2.render_help();
    println!("{}", help);
}
EOF
