        if has_config && has_isolated {
            eprintln!("error: the argument '--isolated' cannot be used with '--config <CONFIG>'\n\nUsage: executable --isolated [COMMAND]\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if let Some((sub_name, sub_matches)) = matches.subcommand() {
        match sub_name {
            "check" => commands::check::handle(sub_matches, false, &matches),
            "fmt" => commands::check::handle(sub_matches, true, &matches),
            "init" => commands::init::handle(sub_matches),
            "rule" => commands::rule::handle(sub_matches),
            "explain" => commands::explain::handle(sub_matches),
            "config" => commands::config::handle(sub_matches),
