use crate::config::{load_effective_config, find_config_file};
use crate::linter::{lint_content, apply_fixes, Issue};
use crate::output;
use std::path::{Path, PathBuf};

fn is_markdown(path: &Path) -> bool {
    if let Some(ext) = path.extension() {
        let s = ext.to_string_lossy().to_lowercase();
        matches!(s.as_str(), "md" | "markdown" | "mdown" | "mkd" | "mdwn" | "mkdn")
    } else { false }
}

fn is_excluded(path: &Path, patterns: &[String]) -> bool {
    if patterns.is_empty() { return false; }
    let ps = path.to_string_lossy();
    for pat in patterns {
        if pat.contains('*') || pat.contains('?') {
            if let Ok(g) = glob::Pattern::new(pat) {
                if g.matches(&ps) || g.matches(path.file_name().unwrap_or_default().to_string_lossy().as_ref()) {
                    return true;
                }
                for comp in path.components() {
                    if let Some(s) = comp.as_os_str().to_str() {
                        if g.matches(s) { return true; }
                    }
                }
            }
        } else {
            if ps.contains(pat) { return true; }
            if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
                if fname == pat { return true; }
            }
        }
    }
    false
}

fn is_included(path: &Path, patterns: &[String]) -> bool {
    if patterns.is_empty() { return true; }
    let ps = path.to_string_lossy();
    for pat in patterns {
        if pat.contains('*') || pat.contains('?') {
            if let Ok(g) = glob::Pattern::new(pat) {
                if g.matches(&ps) { return true; }
            }
        } else {
            if ps.contains(pat) { return true; }
        }
    }
    false
}

fn scan_dir(dir: &Path, cfg: &crate::config::EffectiveConfig, exclude_cli: &[String], include_cli: &[String], no_exclude: bool, respect_gitignore: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    if respect_gitignore {
        let mut builder = ignore::WalkBuilder::new(dir);
        builder.hidden(false);
        builder.git_ignore(true);
        for result in builder.build() {
            if let Ok(entry) = result {
                let p = entry.path();
                if p.is_file() && is_markdown(p) {
                    if !no_exclude {
                        if is_excluded(p, &cfg.global.exclude) || is_excluded(p, exclude_cli) { continue; }
                    }
                    if !include_cli.is_empty() && !is_included(p, include_cli) { continue; }
                    files.push(p.to_path_buf());
                }
            }
        }
    } else {
        for entry in walkdir::WalkDir::new(dir).into_iter().filter_map(|e| e.ok()) {
            let p = entry.path();
            if p.is_file() && is_markdown(p) {
                if !no_exclude {
                    if is_excluded(p, &cfg.global.exclude) || is_excluded(p, exclude_cli) { continue; }
                }
                if !include_cli.is_empty() && !is_included(p, include_cli) { continue; }
                files.push(p.to_path_buf());
            }
        }
    }
    files
}

