}

fn determine_exit_code(issues: &[Issue], fail_on: &str, is_fmt: bool, has_fix: bool, has_check_flag: bool, has_diff: bool) -> i32 {
    if fail_on=="never" { return 0; }
    if is_fmt && !has_check_flag && !has_diff { return 0; }
    if issues.is_empty() { return 0; }
    match fail_on {
        "any" => 1,
        "warning" => 1,
        "error" => {
            if issues.iter().any(|i| i.severity=="error") {1} else {0}
        },
        _ => 1,
    }
}
