            // clap will print error and exit automatically if we use print_help? But try_get_matches_from_mut with error returns error that prints?
            // For help and version, clap exits via error code 0? Actually it returns error with Display containing help. We need to handle.
            // If error is help displayed, we should print and exit 0
            // Check if it's help or version
            let code = e.exit_code();
            // e is clap::Error, its Display is the help/error message
            // Print to stdout or stderr depending
            if code == 0 {
                println!("{}", e);
            } else {
                eprintln!("{}", e);
            }
            std::process::exit(code);
        }
    };

    // Global conflicts handling: check if config group has more than one
    let has_config = matches.get_one::<String>("config").is_some();
    let has_no_config = matches.get_flag("no-config");
    let has_isolated = matches.get_flag("isolated");
    let mut count = 0;
    if has_config { count+=1; }
    if has_no_config { count+=1; }
    if has_isolated { count+=1; }
    if count>1 {
        if has_no_config && has_isolated {
            eprintln!("error: the argument '--no-config' cannot be used with '--isolated'\n\nUsage: executable [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if has_config && has_no_config {
            // The original message varies depending where args placed. For simplicity use generic
            eprintln!("error: the argument '--no-config' cannot be used with '--config <CONFIG>'\n\nUsage: executable --no-config [COMMAND]\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if has_config && has_isolated {
            eprintln!("error: the argument '--isolated' cannot be used with '--config <CONFIG>'\n\nUsage: executable --isolated [COMMAND]\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if let Some((sub_name, sub_matches)) = matches.subcommand() {
        match sub_name {
            "check" => commands::check::handle(sub_matches, false, &matches),
            "fmt" => commands::check::handle(sub_matches, true, &matches),
            "init" => commands::init::handle(sub_matches),
            "rule" => commands::rule::handle(sub_matches),
            "explain" => commands::explain::handle(sub_matches),
            "config" => commands::config::handle(sub_matches),
            "server" => commands::server::handle(sub_matches),
            "schema" => commands::schema::handle(sub_matches),
            "import" => commands::import::handle(sub_matches),
            "vscode" => commands::vscode::handle(sub_matches),
            "completions" => commands::completions::handle(sub_matches),
            "clean" => commands::clean::handle(sub_matches),
            "version" => {
                println!("rumdl 0.1.13");
            },
            _ => {}
        }
    } else {
        // No subcommand: print help
        let mut cmd = build_cli();
        let _ = cmd.print_help();
        println!();
    }
}
