pub fn print_github(issues: &[Issue], use_stderr: bool) {
    for issue in issues {
        let level = if issue.severity == "error" { "error" } else { "warning" };
        let end_line = issue.end_line.unwrap_or(issue.line);
        let end_col = issue.end_column.unwrap_or(issue.column+1);
        let out = format!("::{} file={},line={},col={},endLine={},endColumn={},title={}::{}", level, issue.file, issue.line, issue.column, end_line, end_col, issue.rule, issue.message);
        if use_stderr { eprintln!("{}", out); } else { println!("{}", out); }
    }
}

pub fn print_gitlab(issues: &[Issue], use_stderr: bool) {
