pub fn print_junit(issues: &[Issue], use_stderr: bool) {
    let mut xml = String::new();
    xml.push_str(r#"<?xml version="1.0" encoding="UTF-8"?>"#);
    xml.push('\n');
    let files: HashSet<_> = issues.iter().map(|i| &i.file).collect();
    xml.push_str(&format!(r#"<testsuites name="rumdl" tests="{}" failures="{}" errors="0" time="0.007">"#, files.len(), issues.len()));
    xml.push('\n');
    let mut by_file: HashMap<String, Vec<&Issue>> = HashMap::new();
    for iss in issues {
        by_file.entry(iss.file.clone()).or_default().push(iss);
    }
    for (file, list) in by_file {
        xml.push_str(&format!(r#"  <testsuite name="{}" tests="1" failures="{}" errors="0" time="0.000">"#, file, list.len()));
        xml.push('\n');
        xml.push_str(&format!(r#"    <testcase name="Lint {}" classname="rumdl" time="0.000">"#, file));
        xml.push('\n');
        for iss in list {
            xml.push_str(&format!(r#"      <failure type="{}" message="{}">{} at line {}, column {}</failure>"#, iss.rule, iss.message, iss.message, iss.line, iss.column));
            xml.push('\n');
        }
        xml.push_str("    </testcase>\n  </testsuite>\n");
    }
    xml.push_str("</testsuites>\n");
    if use_stderr { eprint!("{}", xml); } else { print!("{}", xml); }
}
