fn build_cli() -> Command {
    let mut cmd = Command::new("executable")
        .version("0.1.13")
        .about("A fast Markdown linter written in Rust (Ru(st) MarkDown Linter)")
        .arg(Arg::new("color").long("color").value_name("COLOR").value_parser(["auto","always","never"]).default_value("auto").help("Control colored output: auto, always, never").global(true))
        .arg(Arg::new("config").long("config").value_name("CONFIG").value_hint(ValueHint::FilePath).help("Path to configuration file").global(true))
