    cmd = cmd.subcommand(Command::new("check").about("Lint Markdown files and print warnings/errors").args(check_args()));
    cmd = cmd.subcommand(Command::new("fmt").about("Format Markdown files (alias for check --fix)").args(check_args()));
    cmd = cmd.subcommand(Command::new("init").about("Initialize a new configuration file"));
    cmd
}

fn main() {
    let mut cmd = build_cli();
