    eprintln!("DEBUG args: {:?}", std::env::args().collect::<Vec<_>>());
    let mut cmd = build_cli();
    let matches = match cmd.try_get_matches_from_mut(std::env::args()) {
        Ok(m) => {
            eprintln!("DEBUG ok subcommand: {:?}", m.subcommand_name());
            m
