use crate::config::EffectiveConfig;
use std::collections::HashSet;

#[derive(Debug, Clone)]
pub struct Issue {
    pub file: String,
    pub line: usize,
    pub column: usize,
    pub rule: String,
    pub message: String,
    pub severity: String,
    pub fixable: bool,
    pub fix_range: Option<(usize, usize)>,
    pub fix_replacement: Option<String>,
    pub end_line: Option<usize>,
    pub end_column: Option<usize>,
}

pub fn get_all_rules_codes() -> Vec<String> {
    vec![
        "MD001","MD003","MD004","MD005","MD007","MD009","MD010","MD011","MD012","MD013","MD014","MD018","MD019","MD020","MD021","MD022","MD023","MD024","MD025","MD026","MD027","MD028","MD029","MD030","MD031","MD032","MD033","MD034","MD035","MD036","MD037","MD038","MD039","MD040","MD041","MD042","MD043","MD044","MD045","MD046","MD047","MD048","MD049","MD050","MD051","MD052","MD053","MD054","MD055","MD056","MD057","MD058","MD059","MD060","MD061","MD062","MD063","MD064","MD065","MD066","MD067","MD068","MD069","MD070","MD071","MD072","MD073"
    ].into_iter().map(|s| s.to_string()).collect()
}

fn compute_line_starts(content: &str) -> Vec<usize> {
    let mut starts = vec![0];
    for (i, ch) in content.char_indices() {
        if ch == '\n' {
            starts.push(i+1);
        }
    }
    starts
}

pub fn lint_content(content: &str, file_path: &str, config: &EffectiveConfig, cli_disable: &[String], cli_enable: &[String], extend_disable: &[String], extend_enable: &[String]) -> Vec<Issue> {
    let mut enabled: HashSet<String> = get_all_rules_codes().into_iter().collect();

    if !config.global.disable.is_empty() {
        for d in &config.global.disable {
            enabled.remove(&d.to_uppercase());
        }
    }
    if !config.global.enable.is_empty() {
        let set: HashSet<String> = config.global.enable.iter().map(|s| s.to_uppercase()).collect();
        enabled = set;
    }
    if !cli_disable.is_empty() {
        for d in cli_disable {
            for part in d.split(',') {
                enabled.remove(part.trim().to_uppercase().as_str());
            }
        }
    }
    if !cli_enable.is_empty() {
        let mut new_set = HashSet::new();
        for e in cli_enable {
            for part in e.split(',') {
                new_set.insert(part.trim().to_uppercase());
            }
        }
        enabled = new_set;
    }
    for d in extend_disable {
        for part in d.split(',') {
            enabled.remove(part.trim().to_uppercase().as_str());
        }
    }
    for e in extend_enable {
        for part in e.split(',') {
            enabled.insert(part.trim().to_uppercase());
        }
    }

    let line_starts = compute_line_starts(content);
    let lines: Vec<&str> = content.lines().collect();
    let mut issues = Vec::new();
    let mut prev_heading_level: Option<usize> = None;
    let mut heading_contents: Vec<String> = Vec::new();
    let mut top_level_count = 0;

    for (idx, line) in lines.iter().enumerate() {
        let line_num = idx + 1;
        let line_start = line_starts.get(idx).cloned().unwrap_or(0);

        if enabled.contains("MD009") {
            let trimmed = line.trim_end_matches(|c| c == ' ' || c == '\t');
            let trailing_len = line.len() - trimmed.len();
            if trailing_len > 0 {
                let allow_br = trailing_len == 2;
                if !allow_br {
                    issues.push(Issue {
                        file: file_path.to_string(),
                        line: line_num,
                        column: trimmed.len() + 1,
                        rule: "MD009".to_string(),
                        message: format!("{} trailing spaces found", trailing_len),
                        severity: "warning".to_string(),
                        fixable: true,
                        fix_range: Some((line_start + trimmed.len(), line_start + line.len())),
                        fix_replacement: Some("".to_string()),
                        end_line: Some(line_num),
                        end_column: Some(line.len()+1),
                    });
                }
            }
        }

        if enabled.contains("MD010") {
            if let Some(col) = line.find('\t') {
                issues.push(Issue {
                    file: file_path.to_string(),
                    line: line_num,
                    column: col+1,
                    rule: "MD010".to_string(),
                    message: "Tab character found".to_string(),
                    severity: "warning".to_string(),
                    fixable: true,
                    fix_range: None,
                    fix_replacement: None,
                    end_line: None,
                    end_column: None,
                });
            }
        }

        if enabled.contains("MD013") {
            let limit = 80;
            if line.chars().count() > limit {
                issues.push(Issue {
                    file: file_path.to_string(),
                    line: line_num,
                    column: limit+1,
                    rule: "MD013".to_string(),
                    message: format!("Line length {} exceeds {} characters", line.chars().count(), limit),
                    severity: "warning".to_string(),
                    fixable: false,
                    fix_range: None,
                    fix_replacement: None,
                    end_line: None,
                    end_column: None,
                });
            }
        }

        if enabled.contains("MD018") {
            let trimmed_start = line.trim_start();
            if trimmed_start.starts_with('#') {
                let mut hash_count = 0;
                for ch in trimmed_start.chars() {
                    if ch == '#' { hash_count+=1; } else { break; }
                }
                if hash_count>0 && hash_count<=6 {
                    let rest = &trimmed_start[hash_count..];
                    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') {
                        issues.push(Issue {
                            file: file_path.to_string(),
                            line: line_num,
                            column: line.find('#').unwrap_or(0)+hash_count+1,
                            rule: "MD018".to_string(),
                            message: "No space after hash in heading".to_string(),
                            severity: "warning".to_string(),
                            fixable: true,
                            fix_range: None,
                            fix_replacement: None,
                            end_line: None,
                            end_column: None,
                        });
                    }
                }
            }
        }

        if enabled.contains("MD019") {
            let trimmed_start = line.trim_start();
            if trimmed_start.starts_with('#') {
                let mut hash_count = 0;
                for ch in trimmed_start.chars() {
                    if ch == '#' { hash_count+=1; } else { break; }
                }
                if hash_count>0 {
                    let rest = &trimmed_start[hash_count..];
                    if rest.starts_with("  ") {
                        issues.push(Issue {
                            file: file_path.to_string(),
                            line: line_num,
                            column: line.find('#').unwrap_or(0)+hash_count+1,
                            rule: "MD019".to_string(),
                            message: "Multiple spaces after hash in heading".to_string(),
                            severity: "warning".to_string(),
                            fixable: true,
                            fix_range: None,
                            fix_replacement: None,
                            end_line: None,
                            end_column: None,
                        });
                    }
                }
            }
        }

        if enabled.contains("MD041") && line_num==1 {
            let trimmed = line.trim();
            if !trimmed.starts_with("# ") {
                issues.push(Issue {
                    file: file_path.to_string(),
                    line: 1,
                    column: 1,
                    rule: "MD041".to_string(),
                    message: "First line in file should be a level 1 heading".to_string(),
                    severity: "warning".to_string(),
                    fixable: false,
                    fix_range: None,
                    fix_replacement: None,
                    end_line: None,
                    end_column: None,
                });
            }
        }

        let trimmed = line.trim();
        if trimmed.starts_with('#') {
            let mut level = 0;
            for ch in trimmed.chars() {
                if ch == '#' { level+=1; } else { break; }
            }
            if level>=1 && level<=6 {
                let after = trimmed.chars().nth(level);
                if after.is_none() || after==Some(' ') || after==Some('\t') {
                    if enabled.contains("MD001") {
                        if let Some(prev) = prev_heading_level {
                            if level > prev+1 {
                                let rest = trimmed[level..].trim_start();
                                issues.push(Issue {
                                    file: file_path.to_string(),
                                    line: line_num,
                                    column: 1,
                                    rule: "MD001".to_string(),
                                    message: format!("Expected heading level {}, but found heading level {}", prev+1, level),
                                    severity: "error".to_string(),
                                    fixable: true,
                                    fix_range: Some((line_start, line_start+line.len())),
                                    fix_replacement: Some(format!("{} {}", "#".repeat(prev+1), rest)),
                                    end_line: None,
                                    end_column: None,
                                });
                            }
                        }
                    }
                    prev_heading_level = Some(level);
                    if level==1 {
                        top_level_count+=1;
                        if top_level_count>1 && enabled.contains("MD025") {
                            issues.push(Issue {
                                file: file_path.to_string(),
                                line: line_num,
                                column: 1,
                                rule: "MD025".to_string(),
                                message: "Multiple top-level headings (level 1) in the same document".to_string(),
                                severity: "warning".to_string(),
                                fixable: true,
                                fix_range: None,
                                fix_replacement: None,
                                end_line: None,
                                end_column: None,
                            });
                        }
                    }
                    if enabled.contains("MD024") {
                        let heading_text = trimmed[level..].trim().to_lowercase();
                        if heading_contents.contains(&heading_text) {
                            issues.push(Issue {
                                file: file_path.to_string(),
                                line: line_num,
                                column: 1,
                                rule: "MD024".to_string(),
                                message: "Multiple headings with the same content".to_string(),
                                severity: "warning".to_string(),
                                fixable: false,
                                fix_range: None,
                                fix_replacement: None,
                                end_line: None,
                                end_column: None,
                            });
                        } else {
                            heading_contents.push(heading_text);
                        }
                    }
                    if enabled.contains("MD022") {
                        if line_num>1 {
                            let prev_line = lines[idx-1];
                            if !prev_line.trim().is_empty() {
                                issues.push(Issue {
                                    file: file_path.to_string(),
                                    line: line_num,
                                    column: 1,
                                    rule: "MD022".to_string(),
                                    message: "Expected 1 blank line above heading".to_string(),
                                    severity: "warning".to_string(),
                                    fixable: true,
                                    fix_range: Some((line_start, line_start)),
                                    fix_replacement: Some("\n".to_string()),
                                    end_line: None,
                                    end_column: None,
                                });
                            }
                        }
                        if line_num < lines.len() {
                            let next_line = lines[idx+1];
                            if !next_line.trim().is_empty() {
                                issues.push(Issue {
                                    file: file_path.to_string(),
                                    line: line_num,
                                    column: 1,
                                    rule: "MD022".to_string(),
                                    message: "Expected 1 blank line below heading".to_string(),
                                    severity: "warning".to_string(),
                                    fixable: true,
                                    fix_range: Some((line_start+line.len(), line_start+line.len())),
                                    fix_replacement: Some("\n".to_string()),
                                    end_line: None,
                                    end_column: None,
                                });
                            }
                        }
                    }
                }
            }
        }

        if enabled.contains("MD012") && line.trim().is_empty() {
            if idx>0 && lines[idx-1].trim().is_empty() {
                issues.push(Issue {
                    file: file_path.to_string(),
                    line: line_num,
                    column: 1,
                    rule: "MD012".to_string(),
                    message: "Multiple consecutive blank lines".to_string(),
                    severity: "warning".to_string(),
                    fixable: true,
                    fix_range: None,
                    fix_replacement: None,
                    end_line: None,
                    end_column: None,
                });
            }
        }

        if enabled.contains("MD064") {
            let without_leading = line.trim_start();
            let leading_spaces = line.len() - without_leading.len();
            let content_part = &line[leading_spaces..];
            if !content_part.trim().is_empty() {
                let trimmed_end = content_part.trim_end();
                let inner = if content_part.len() > trimmed_end.len() {
                    &content_part[..trimmed_end.len()]
                } else {
                    content_part
                };
                if inner.contains("  ") {
                    if let Some(pos) = inner.find("  ") {
                        let mut count = 0;
                        for ch in inner[pos..].chars() {
                            if ch == ' ' { count+=1; } else { break; }
                        }
                        issues.push(Issue {
                            file: file_path.to_string(),
                            line: line_num,
                            column: leading_spaces + pos + 1,
                            rule: "MD064".to_string(),
                            message: format!("Multiple consecutive spaces ({}) found", count),
                            severity: "warning".to_string(),
                            fixable: true,
                            fix_range: Some((line_start+leading_spaces+pos, line_start+leading_spaces+pos+count)),
                            fix_replacement: Some(" ".to_string()),
                            end_line: None,
                            end_column: None,
                        });
                    }
                }
            }
        }
    }

    if enabled.contains("MD047") {
        if !content.ends_with('\n') && !content.is_empty() {
            let line_num = lines.len();
            let col = lines.last().map(|l| l.len()+1).unwrap_or(1);
            let total_len = content.len();
            issues.push(Issue {
                file: file_path.to_string(),
                line: line_num,
                column: col,
                rule: "MD047".to_string(),
                message: "Files should end with a single newline character".to_string(),
                severity: "warning".to_string(),
                fixable: true,
                fix_range: Some((total_len, total_len)),
                fix_replacement: Some("\n".to_string()),
                end_line: None,
                end_column: None,
            });
        }
    }

    issues
}

pub fn apply_fixes(original: &str, issues: &[Issue]) -> String {
    let mut lines: Vec<String> = original.lines().map(|s| s.to_string()).collect();
    let has_trailing_newline = original.ends_with('\n');
    let mut sorted = issues.to_vec();
    sorted.sort_by(|a,b| b.line.cmp(&a.line));
    for issue in sorted {
        if !issue.fixable { continue; }
        let line_idx = issue.line.saturating_sub(1);
        if line_idx >= lines.len() { continue; }
        match issue.rule.as_str() {
            "MD009" => {
                lines[line_idx] = lines[line_idx].trim_end().to_string();
            },
            "MD001" => {
                if let Some(repl) = &issue.fix_replacement {
                    lines[line_idx] = repl.clone();
                }
            },
            "MD022" => {
                if issue.message.contains("above") {
                    if line_idx>0 && !lines[line_idx-1].trim().is_empty() {
                        lines.insert(line_idx, "".to_string());
                    }
                } else if issue.message.contains("below") {
                    if line_idx+1 < lines.len() && !lines[line_idx+1].trim().is_empty() {
                        lines.insert(line_idx+1, "".to_string());
                    } else if line_idx+1 == lines.len() {
                        lines.push("".to_string());
                    }
                }
            },
            "MD012" => {
                if lines[line_idx].trim().is_empty() && line_idx>0 && lines[line_idx-1].trim().is_empty() {
                    lines.remove(line_idx);
                }
            },
            "MD064" => {
                let mut new_line = lines[line_idx].clone();
                while new_line.contains("  ") {
                    new_line = new_line.replace("  ", " ");
                }
                lines[line_idx] = new_line;
            },
            _ => {}
        }
    }
    let mut result = lines.join("\n");
    if has_trailing_newline || !result.ends_with('\n') {
        if !result.ends_with('\n') {
            result.push('\n');
        }
    }
    while result.ends_with("\n\n") {
        result.pop();
    }
    if !result.ends_with('\n') {
        result.push('\n');
    }
    result
}
