        if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
    }
}

pub fn print_grouped(issues: &[Issue], use_stderr: bool) {
    let mut by_file: HashMap<String, Vec<&Issue>> = HashMap::new();
    for issue in issues {
        by_file.entry(issue.file.clone()).or_default().push(issue);
    }
    let mut files: Vec<_> = by_file.keys().cloned().collect();
    files.sort();
    for file in files {
        if let Some(list) = by_file.get(&file) {
            let header = format!("{}:", file);
            if use_stderr { eprintln!("{}", header); } else { println!("{}", header); }
            let mut by_rule: HashMap<String, Vec<&&Issue>> = HashMap::new();
            for iss in list {
                by_rule.entry(iss.rule.clone()).or_default().push(iss);
            }
            let mut rules: Vec<_> = by_rule.keys().cloned().collect();
            rules.sort();
            for rule in rules {
                if let Some(r_issues) = by_rule.get(&rule) {
