use std::io::{BufRead, Write};

pub fn handle(_sub: &clap::ArgMatches) {
    let stdin = std::io::stdin();
    let mut stdout = std::io::stdout();
    let mut reader = std::io::BufReader::new(stdin);
    let mut has_written = false;
    loop {
        let mut content_length: Option<usize> = None;
        let mut headers_done = false;
        let mut raw_line = String::new();
        let mut lines_buf = Vec::new();
        loop {
            raw_line.clear();
            match reader.read_line(&mut raw_line) {
                Ok(0) => break,
                Ok(_) => {
                    let trimmed = raw_line.trim();
                    if trimmed.is_empty() {
                        headers_done = true;
                        break;
                    }
                    if trimmed.to_lowercase().starts_with("content-length:") {
                        if let Some(val) = trimmed.split(':').nth(1) {
                            content_length = val.trim().parse().ok();
                        }
                    } else {
                        lines_buf.push(raw_line.clone());
                    }
                },
                Err(_) => break,
            }
        }
        if !headers_done && lines_buf.is_empty() && content_length.is_none() {
            break;
        }
        if let Some(len) = content_length {
            let mut buf = vec![0; len];
            if std::io::Read::read_exact(&mut reader, &mut buf).is_err() { break; }
            let resp = "Content-Length: 75\r\n\r\n{\"jsonrpc\":\"2.0\",\"error\":{\"code\":-32700,\"message\":\"Parse error\"},\"id\":null}";
            let _ = stdout.write_all(resp.as_bytes());
            let _ = stdout.flush();
            has_written = true;
            break;
        } else if !lines_buf.is_empty() {
            let resp = "Content-Length: 75\r\n\r\n{\"jsonrpc\":\"2.0\",\"error\":{\"code\":-32700,\"message\":\"Parse error\"},\"id\":null}";
            let _ = stdout.write_all(resp.as_bytes());
            let _ = stdout.flush();
            has_written = true;
            break;
        } else {
            break;
        }
    }
}
