pub fn handle(sub: &clap::ArgMatches) {
    if sub.get_flag("list-categories") {
        println!("Available categories:");
        let cats = vec![
            ("blockquote", 1),
            ("code-block", 4),
            ("emphasis", 1),
            ("front-matter", 1),
            ("heading", 11),
            ("html", 1),
            ("link", 7),
            ("list", 7),
            ("other", 29),
            ("whitespace", 5),
        ];
        for (cat, count) in cats {
            println!("  {} ({} rules)", cat, count);
        }
        return;
    }

    if let Some(rule_name) = sub.get_one::<String>("rule") {
        let all = get_all_rules();
        if let Some(rule) = all.iter().find(|r| r.code.eq_ignore_ascii_case(rule_name) || r.name.eq_ignore_ascii_case(rule_name)) {
            let fmt = sub.get_one::<String>("output-format").map(|s| s.as_str()).unwrap_or("text");
            match fmt {
                "json" => {
                    println!(r#"{{"code":"{}","name":"{}","aliases":[],"summary":"{}","category":"{}","fix":"{}","fix_availability":"Always","url":"https://rumdl.dev/{}/"}}"#, rule.code, rule.name, rule.summary, rule.category, rule.fix, rule.code.to_lowercase());
                },
                "json-lines" => {
                    println!(r#"{{"code":"{}","name":"{}","aliases":[],"summary":"{}","category":"{}","fix":"{}","fix_availability":"Always","url":"https://rumdl.dev/{}/"}}"#, rule.code, rule.name, rule.summary, rule.category, rule.fix, rule.code.to_lowercase());
                },
                _ => {
                    println!("{} - {}", rule.code, rule.summary);
                    println!();
                    println!("Name: {}", rule.name);
                    println!("Category: {}", rule.category);
                    println!("Fix: {}", rule.fix);
                    println!("Documentation: https://rumdl.dev/{}/", rule.code.to_lowercase());
                    let doc_path = format!("docs/{}.md", rule.code.to_lowercase());
                    if let Ok(content) = std::fs::read_to_string(&doc_path) {
                        println!();
                        println!("{}", content);
                    }
                }
            }
        } else {
            eprintln!("Rule '{}' not found.", rule_name);
            std::process::exit(2);
        }
    } else {
        let fmt = sub.get_one::<String>("output-format").map(|s| s.as_str()).unwrap_or("text");
        let all = get_all_rules();
        let filtered: Vec<_> = all.iter().filter(|r| {
            if let Some(cat) = sub.get_one::<String>("category") {
                r.category.eq_ignore_ascii_case(cat.as_str())
            } else { true }
        }).collect();

        match fmt {
            "json" => {
                println!("[");
                for (i, r) in filtered.iter().enumerate() {
