use crate::config::{load_effective_config, find_config_file, get_default_rule_config};

pub fn handle(sub: &clap::ArgMatches) {
    match sub.subcommand() {
        Some(("get", get_sub)) => {
            let key = get_sub.get_one::<String>("key").unwrap();
            let cfg = load_effective_config(get_sub);
            if !key.contains('.') {
                eprintln!("Key must be in the form global.key or MDxxx.key");
                std::process::exit(2);
            }
            let parts: Vec<&str> = key.splitn(2, '.').collect();
            let section = parts[0];
            let subkey = parts[1];
            if section=="global" {
                match subkey {
                    "disable" => println!("global.disable = {:?} [from {}]", cfg.global.disable, cfg.source),
                    "enable" => println!("global.enable = {:?} [from {}]", cfg.global.enable, cfg.source),
                    "exclude" => println!("global.exclude = {:?} [from {}]", cfg.global.exclude, cfg.source),
                    "include" => println!("global.include = {:?} [from {}]", cfg.global.include, cfg.source),
                    "respect_gitignore" | "respect-gitignore" => println!("global.respect_gitignore = {} [from {}]", cfg.global.respect_gitignore, cfg.source),
                    "flavor" => println!("global.flavor = {} [from {}]", cfg.global.flavor, cfg.source),
                    _ => {
                        eprintln!("Unknown global key: {}", subkey);
                        std::process::exit(2);
                    }
                }
            } else if section.to_uppercase().starts_with("MD") {
                let rule_code = section.to_uppercase();
                let all = crate::commands::rule::get_all_rules_static();
                if !all.iter().any(|(c,_)| c==&rule_code) {
                    eprintln!("Unknown rule: {}", rule_code);
                    std::process::exit(2);
                }
                if let Some(rule_cfg) = cfg.rule_configs.get(&rule_code) {
                    if let Some(val) = rule_cfg.get(subkey) {
                        println!("{}.{} = {} [from {}]", rule_code, subkey, val, cfg.source);
                    } else if let Some(val) = rule_cfg.get(&subkey.replace('-', "_")) {
                        println!("{}.{} = {} [from {}]", rule_code, subkey, val, cfg.source);
                    } else {
                        let def = get_default_rule_config(&rule_code, subkey);
                        println!("{}.{} = {} [from default]", rule_code, subkey, def);
                    }
                } else {
                    let def = get_default_rule_config(&rule_code, subkey);
                    println!("{}.{} = {} [from default]", rule_code, subkey, def);
                }
