                    } else {
                        println!("No configuration file found (using defaults)");
                    }
                }
            }
        },
        None => {
            let cfg = load_effective_config(sub);
            let no_defaults = sub.get_flag("no-defaults");
            let output = sub.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("text");
            if output=="json" {
                println!(r#"{{"global":{{"enable":{:?},"disable":{:?},"exclude":{:?},"include":{:?},"respect-gitignore":{},"flavor":"{}"}}}}"#, cfg.global.enable, cfg.global.disable, cfg.global.exclude, cfg.global.include, cfg.global.respect_gitignore, cfg.global.flavor);
