pub fn handle(sub: &clap::ArgMatches) {
    let file_path = sub.get_one::<String>("file").unwrap();
    let dry_run = sub.get_flag("dry-run");
    let format = sub.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("toml");
    let output_path = sub.get_one::<String>("output").map(|s| s.as_str()).unwrap_or(".rumdl.toml");

    let content = match std::fs::read_to_string(file_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Failed to read file {}: {}", file_path, e);
            std::process::exit(2);
        }
    };

    let mut disabled = Vec::new();
    if let Ok(json_val) = serde_json::from_str::<serde_json::Value>(&content) {
        if let Some(obj) = json_val.as_object() {
            for (k,v) in obj {
                if v.as_bool()==Some(false) {
                    disabled.push(k.clone());
                }
            }
        }
    } else if let Ok(yaml_val) = serde_yaml::from_str::<serde_yaml::Value>(&content) {
        if let Some(map) = yaml_val.as_mapping() {
            for (k,v) in map {
                if let Some(ks) = k.as_str() {
                    if v.as_bool()==Some(false) {
                        disabled.push(ks.to_string());
                    }
                }
            }
        }
    }

    disabled.sort();

    let toml_out = if disabled.is_empty() {
        "[global]\ndisable = []\n".to_string()
    } else {
        let inner = disabled.iter().map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", ");
        format!("[global]\ndisable = [{}]\n", inner)
    };

    let json_out = if disabled.is_empty() {
        "{\n  \"global\": {\n    \"disable\": []\n  }\n}\n".to_string()
    } else {
        let inner = disabled.iter().map(|s| format!("    \"{}\"", s)).collect::<Vec<_>>().join(",\n");
        format!("{{\n  \"global\": {{\n    \"disable\": [\n{}\n    ]\n  }}\n}}\n", inner)
    };

    if dry_run {
        if format=="json" {
            print!("{}", json_out);
        } else {
            print!("{}", toml_out);
        }
    } else {
        if format=="json" {
            std::fs::write(output_path, json_out).unwrap();
        } else {
            std::fs::write(output_path, toml_out).unwrap();
        }
        println!("Converted markdownlint config from '{}' to '{}'", file_path, output_path);
        println!("You can now use: rumdl check --config {} .", output_path);
    }
}
'''
