use crate::linter::Issue;
use std::collections::{HashMap, HashSet};
use serde_json::json;

pub fn format_json(issues: &[Issue]) -> String {
    let mut arr = Vec::new();
    for issue in issues {
        let mut obj = json!({
            "file": issue.file,
            "line": issue.line,
            "column": issue.column,
            "rule": issue.rule,
            "message": issue.message,
            "severity": issue.severity,
            "fixable": issue.fixable,
            "fix": null
        });
        if issue.fixable {
            if let Some((start,end)) = issue.fix_range {
                let repl = issue.fix_replacement.clone().unwrap_or_default();
                obj["fix"] = json!({
                    "range": {"start": start, "end": end},
                    "replacement": repl
                });
            } else if let Some(repl) = &issue.fix_replacement {
                obj["fix"] = json!({
                    "range": {"start": 0, "end": 0},
                    "replacement": repl
                });
            } else {
                obj["fix"] = json!({
                    "range": {"start": 0, "end": 0},
                    "replacement": ""
                });
            }
        }
        arr.push(obj);
    }
    serde_json::to_string_pretty(&arr).unwrap()
}

pub fn print_grouped(issues: &[Issue], use_stderr: bool) {
    let mut by_file: HashMap<String, Vec<&Issue>> = HashMap::new();
    for issue in issues {
        by_file.entry(issue.file.clone()).or_default().push(issue);
    }
    let mut files: Vec<_> = by_file.keys().cloned().collect();
    files.sort();
    for file in files {
        if let Some(list) = by_file.get(&file) {
            let header = format!("{}:", file);
            if use_stderr { eprintln!("{}", header); } else { println!("{}", header); }
            let mut by_rule: HashMap<String, Vec<&&Issue>> = HashMap::new();
            for iss in list {
                by_rule.entry(iss.rule.clone()).or_default().push(iss);
            }
            let mut rules: Vec<_> = by_rule.keys().cloned().collect();
            rules.sort();
            for rule in rules {
                if let Some(r_issues) = by_rule.get(&rule) {
                    let rule_header = format!("  {}:", rule);
                    if use_stderr { eprintln!("{}", rule_header); } else { println!("{}", rule_header); }
                    for iss in r_issues {
                        let line = format!("    {}:{} {}{}", iss.line, iss.column, iss.message, if iss.fixable { " (fixable)" } else { "" });
                        if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
                    }
                }
            }
        }
    }
}
