    });
    let shell = match shell_str.as_str() {
        "bash" => Shell::Bash,
        "zsh" => Shell::Zsh,
        "fish" => Shell::Fish,
        "elvish" => Shell::Elvish,
        "powershell" => Shell::PowerShell,
        _ => {
            eprintln!("Unknown shell: {}", shell_str);
            std::process::exit(2);
        }
    };
    let mut cmd = build_cli();
    clap_complete::generate(shell, &mut cmd, "rumdl", &mut std::io::stdout());
}
