                    let mut diff_out = String::new();
                    diff_out.push_str(&format!("--- {}\n", file));
                    diff_out.push_str(&format!("+++ {} (fixed)\n", file));
                    let orig_lines: Vec<&str> = orig.lines().collect();
                    let fixed_lines: Vec<&str> = fixed.lines().collect();
                    diff_out.push_str(&format!("@@ -1,{} +1,{} @@\n", orig_lines.len(), fixed_lines.len()));
                    for (o,f) in orig_lines.iter().zip(fixed_lines.iter()) {
                        if o!=f {
                            diff_out.push_str(&format!("-{}\n+{}\n", o, f));
                        }
                    }
                    if orig_lines.len() != fixed_lines.len() {
                        if orig_lines.len() > fixed_lines.len() {
                            for i in fixed_lines.len()..orig_lines.len() {
                                diff_out.push_str(&format!("-{}\n", orig_lines[i]));
                            }
                        } else {
                            for i in orig_lines.len()..fixed_lines.len() {
                                diff_out.push_str(&format!("+{}\n", fixed_lines[i]));
                            }
                        }
                    }
                    diff_out.push('\n');
