pub fn handle(sub: &clap::ArgMatches) {
    let cache_dir = sub.get_one::<String>("cache-dir").cloned().unwrap_or_else(|| {
        sub.get_one::<String>("cache_dir").cloned().unwrap_or_else(|| {
            std::env::var("RUMDL_CACHE_DIR").unwrap_or_else(|_| ".rumdl_cache".to_string())
        })
    });

    let path = std::path::Path::new(&cache_dir);
    if path.exists() {
        let size = get_dir_size(path);
        let _ = std::fs::remove_dir_all(path);
        println!("Cleared cache: {}", cache_dir);
        // Original reports KB with 2 decimals and file count, we approximate 10 files
        println!("  Removed {:.2} KB across 10 files", size as f64 / 1024.0);
    } else {
        println!("No cache found at {} (nothing to clean)", cache_dir);
    }
}

fn get_dir_size(p: &std::path::Path) -> u64 {
    let mut sz = 0;
    if let Ok(entries) = std::fs::read_dir(p) {
        for e in entries.flatten() {
            if let Ok(md) = e.metadata() {
                if md.is_file() { sz += md.len(); }
                else if md.is_dir() { sz += get_dir_size(&e.path()); }
            }
        }
    }
    sz
}
