    let extend_enable = sub.get_one::<String>("extend-enable").map(|s| s.split(',').map(|x| x.trim().to_string()).collect::<Vec<_>>()).unwrap_or_default();
    let exclude_cli = sub.get_one::<String>("exclude").map(|s| s.split(',').map(|x| x.trim().to_string()).collect::<Vec<_>>()).unwrap_or_default();
    let include_cli = sub.get_one::<String>("include").map(|s| s.split(',').map(|x| x.trim().to_string()).collect::<Vec<_>>()).unwrap_or_default();
    let no_exclude = sub.get_flag("no-exclude");
    let force_exclude = sub.get_flag("force-exclude");

    let mut paths: Vec<String> = Vec::new();
    if let Some(p) = sub.get_many::<String>("paths") {
        for v in p { paths.push(v.clone()); }
    }

    let stdin_flag = sub.get_flag("stdin");
    let mut using_stdin = false;
    let mut stdin_content = String::new();
    if stdin_flag || paths.iter().any(|p| p=="-") {
        using_stdin = true;
        use std::io::Read;
        std::io::stdin().read_to_string(&mut stdin_content).unwrap_or(0);
        paths.retain(|p| p!="-");
    }

    if paths.is_empty() && !using_stdin {
        paths.push(".".to_string());
    }

    let mut files_to_lint: Vec<PathBuf> = Vec::new();
    let mut explicit_files: Vec<PathBuf> = Vec::new();

    for p_str in &paths {
        let p = PathBuf::from(p_str);
        if !p.exists() {
            if p_str != "." {
                eprintln!("Path does not exist: {}", p_str);
                std::process::exit(2);
            }
            continue;
        }
        if p.is_file() {
            explicit_files.push(p.clone());
            files_to_lint.push(p);
        } else if p.is_dir() {
            let mut found = scan_dir(&p, &effective_config, &exclude_cli, &include_cli, no_exclude, respect_gitignore);
            files_to_lint.append(&mut found);
        }
    }

    let mut all_issues: Vec<Issue> = Vec::new();
    let mut files_checked = 0;
    let mut original_contents: std::collections::HashMap<String, String> = std::collections::HashMap::new();

    if using_stdin {
        let display_name = if let Some(fname) = sub.get_one::<String>("stdin-filename") {
            fname.clone()
        } else {
            "<stdin>".to_string()
        };
        let issues = lint_content(&stdin_content, &display_name, &effective_config, &disable, &enable, &extend_disable, &extend_enable);
        if has_fix || is_fmt {
            let fixed = apply_fixes(&stdin_content, &issues);
            if has_diff {
                if fixed != stdin_content {
                    let diff = format!("--- {}\n+++ {} (fixed)\n@@\n-{}\n+{}\n", display_name, display_name, stdin_content.lines().next().unwrap_or(""), fixed.lines().next().unwrap_or(""));
                    if use_stderr { eprint!("{}", diff); } else { print!("{}", diff); }
                }
                let fixable = issues.iter().filter(|i| i.fixable).count();
                let total = issues.len();
                if total>0 && !quiet && !silent {
                    let msg = format!("Fixed: Fixed {}/{} issues in 1 file (15ms)", fixable, total);
                    if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                }
                let code = if is_fmt && !has_check_flag {0} else { if issues.is_empty() {0} else {1}};
                std::process::exit(code);
            } else {
                print!("{}", fixed);
                let code = if is_fmt {0} else { if issues.iter().any(|i| !i.fixable) {1} else {0}};
                std::process::exit(code);
            }
        } else {
            if !silent {
                if !quiet {
                    match output_format.as_str() {
                        "json" => {
                            println!("{}", crate::output::format_json(&issues));
                        },
                        _ => {
                            for iss in &issues {
                                let marker = if iss.fixable { " [*]" } else { "" };
                                let line = format!("{}:{}:{}: [{}] {}{}", iss.file, iss.line, iss.column, iss.rule, iss.message, marker);
                                if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
                            }
                            if issues.is_empty() {
                                if sub.get_one::<String>("stdin-filename").is_some() {
                                    let msg = format!("No issues found in {}", display_name);
                                    if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                                } else {
                                    let msg = "No issues found in <stdin>";
                                    if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                                }
                            } else {
                                let msg = format!("\nFound {} issue(s) in {}", issues.len(), display_name);
                                if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                            }
                        }
                    }
                }
            }
            let code = match fail_on.as_str() {
                "never" => 0,
                "error" => if issues.iter().any(|i| i.severity=="error") {1} else {0},
                _ => if issues.is_empty() {0} else {1},
            };
            std::process::exit(code);
        }
    } else {
        for file_path in &files_to_lint {
            let is_explicit = explicit_files.iter().any(|e| e==file_path);
            if !no_exclude && !is_explicit {
                if is_excluded(file_path, &effective_config.global.exclude) || is_excluded(file_path, &exclude_cli) { continue; }
            }
            if is_explicit && force_exclude {
                if is_excluded(file_path, &effective_config.global.exclude) || is_excluded(file_path, &exclude_cli) { continue; }
            }
            if !include_cli.is_empty() && !is_explicit {
                if !is_included(file_path, &include_cli) { continue; }
            }
            let content = match std::fs::read_to_string(file_path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            original_contents.insert(file_path.to_string_lossy().to_string(), content.clone());
            let display = if show_full_path {
                std::fs::canonicalize(file_path).unwrap_or(file_path.clone()).to_string_lossy().to_string()
            } else {
                file_path.to_string_lossy().to_string()
            };
            let issues = lint_content(&content, &display, &effective_config, &disable, &enable, &extend_disable, &extend_enable);
            all_issues.extend(issues);
        }
        files_checked = files_to_lint.len();

        let mut by_file: std::collections::HashMap<String, Vec<Issue>> = std::collections::HashMap::new();
        for iss in &all_issues {
            by_file.entry(iss.file.clone()).or_default().push(iss.clone());
        }

        if verbose {
            if !quiet && !silent {
                // Print enabled rules with summaries
                let all_rules = crate::commands::rule::get_all_rules_static();
                let mut enabled_for_verbose = Vec::new();
                for (code, summary) in all_rules {
                    // Check if enabled based on same logic? For simplicity, use same enabled set as lint would
                    // We already computed enabled via earlier logic but we lost it; for verbose we can just list all enabled rules from config
                    // Determine if rule would be enabled
                    let mut enabled_set = crate::linter::get_all_rules_codes().into_iter().collect::<std::collections::HashSet<_>>();
                    // apply same filters as before (reuse logic)
                    if !effective_config.global.disable.is_empty() {
                        for d in &effective_config.global.disable {
                            enabled_set.remove(&d.to_uppercase());
                        }
                    }
                    // CLI filters
                    if !disable.is_empty() {
                        for d in &disable {
                            for part in d.split(',') {
                                enabled_set.remove(part.trim().to_uppercase().as_str());
                            }
                        }
                    }
                    // ... simplified: just list all if no filter
                    if enabled_set.contains(&code.to_string()) {
                        enabled_for_verbose.push((code, summary));
                    }
                }
                if use_stderr {
                    eprintln!("Enabled rules:");
                    for (c,s) in &enabled_for_verbose {
                        eprintln!("  - {} ({})", c, s);
                    }
                    eprintln!("\nExclude patterns: []");
                    for f in files_to_lint.iter() {
                        eprintln!("Processing file: {}", f.display());
                    }
                } else {
                    println!("Enabled rules:");
                    for (c,s) in &enabled_for_verbose {
                        println!("  - {} ({})", c, s);
                    }
                    println!("\nExclude patterns: []");
                    for f in files_to_lint.iter() {
                        println!("Processing file: {}", f.display());
                    }
                }
            }
        }

        if has_diff {
            for (file, issues) in &by_file {
                let orig = original_contents.get(file).cloned().unwrap_or_default();
                let fixed = apply_fixes(&orig, issues);
                if orig != fixed {
                    let mut diff_out = String::new();
                    diff_out.push_str(&format!("--- {}\n", file));
                    diff_out.push_str(&format!("+++ {} (fixed)\n", file));
                    let orig_lines: Vec<&str> = orig.lines().collect();
                    let fixed_lines: Vec<&str> = fixed.lines().collect();
                    diff_out.push_str(&format!("@@ -1,{} +1,{} @@\n", orig_lines.len(), fixed_lines.len()));
                    for (o,f) in orig_lines.iter().zip(fixed_lines.iter()) {
                        if o!=f {
                            diff_out.push_str(&format!("-{}\n+{}\n", o, f));
                        }
                    }
                    if orig_lines.len() != fixed_lines.len() {
                        if orig_lines.len() > fixed_lines.len() {
                            for i in fixed_lines.len()..orig_lines.len() {
                                diff_out.push_str(&format!("-{}\n", orig_lines[i]));
                            }
                        } else {
                            for i in orig_lines.len()..fixed_lines.len() {
                                diff_out.push_str(&format!("+{}\n", fixed_lines[i]));
                            }
                        }
                    }
                    diff_out.push('\n');
                    if use_stderr { eprint!("{}", diff_out); } else { print!("{}", diff_out); }
                }
            }
            if !quiet && !silent {
                let fixable = all_issues.iter().filter(|i| i.fixable).count();
                let total = all_issues.len();
                if !original_contents.is_empty() {
                    let msg = format!("Fixed: Fixed {}/{} issues in {} file ({}ms)", fixable, total, files_checked, 15);
                    if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                }
            }
            let code = match fail_on.as_str() {
                "never" => 0,
                _ => if all_issues.is_empty() {0} else {1},
            };
            if has_check_flag && all_issues.iter().any(|i| i.fixable) {
                std::process::exit(1);
            }
            // profile handling
            if profile && !quiet && !silent {
                if use_stderr { eprintln!("\nProfiling is disabled."); } else { println!("\nProfiling is disabled."); }
            }
            std::process::exit(code);
        }

        if has_fix && !has_diff {
            for (file, issues) in by_file.clone() {
                let orig = original_contents.get(&file).cloned().unwrap_or_default();
                let fixed = apply_fixes(&orig, &issues);
                if orig != fixed {
                    let _ = std::fs::write(&file, fixed);
                }
            }
            if !quiet && !silent {
                match output_format.as_str() {
                    "json" => {
                        println!("{}", crate::output::format_json(&all_issues));
                    },
                    _ => {
                        for iss in &all_issues {
                            let marker = if iss.fixable { " [fixed]" } else { "" };
                            let line = format!("{}:{}:{}: [{}] {}{}", iss.file, iss.line, iss.column, iss.rule, iss.message, marker);
                            if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
                        }
                        if all_issues.is_empty() {
                            if files_checked==0 {
                                println!("No markdown files found to check.");
                            } else {
                                println!("Success: No issues found in {} file (5ms)", files_checked);
                            }
                        } else {
                            let fixable = all_issues.iter().filter(|i| i.fixable).count();
                            let total = all_issues.len();
                            println!("\nFixed: Fixed {}/{} issues in {} file ({}ms)", fixable, total, files_checked, 19);
                        }
                    }
                }
            }
            let code = if is_fmt {0} else { if all_issues.iter().any(|i| !i.fixable) {1} else {0}};
            if profile && !quiet && !silent {
                if use_stderr { eprintln!("\nProfiling is disabled."); } else { println!("\nProfiling is disabled."); }
            }
            std::process::exit(code);
        }

        if has_check_flag {
            let has_fixable = all_issues.iter().any(|i| i.fixable);
            if has_fixable {
                for (file, issues) in by_file {
                    let orig = original_contents.get(&file).cloned().unwrap_or_default();
                    let fixed = apply_fixes(&orig, &issues);
                    if orig != fixed {
                        let mut diff_out = String::new();
                        diff_out.push_str(&format!("--- {}\n", file));
                        diff_out.push_str(&format!("+++ {} (fixed)\n", file));
                        diff_out.push_str(&format!("@@ -1 +1 @@\n"));
                        for (o,f) in orig.lines().zip(fixed.lines()) {
                            if o!=f {
                                diff_out.push_str(&format!("-{}\n+{}\n", o, f));
                            }
                        }
                        if use_stderr { eprint!("{}", diff_out); } else { print!("{}", diff_out); }
                    }
                }
                if !quiet {
                    let fixable = all_issues.iter().filter(|i| i.fixable).count();
                    let total = all_issues.len();
                    println!("\nFixed: Fixed {}/{} issues in {} file ({}ms)", fixable, total, files_checked, 15);
                }
                if profile && !quiet && !silent {
                    if use_stderr { eprintln!("\nProfiling is disabled."); } else { println!("\nProfiling is disabled."); }
                }
                std::process::exit(1);
            } else {
                if !quiet && !silent {
                    if all_issues.is_empty() {
                        println!("Success: No issues found in {} file (5ms)", files_checked);
                    }
                }
                if profile && !quiet && !silent {
                    if use_stderr { eprintln!("\nProfiling is disabled."); } else { println!("\nProfiling is disabled."); }
                }
                std::process::exit(0);
            }
        }
    }

    if silent {
        let code = match fail_on.as_str() {
            "never" => 0,
            "error" => if all_issues.iter().any(|i| i.severity=="error") {1} else {0},
            _ => if all_issues.is_empty() {0} else {1},
        };
        std::process::exit(code);
    }

    all_issues.sort_by(|a,b| a.file.cmp(&b.file).then(a.line.cmp(&b.line)).then(a.column.cmp(&b.column)));

    match output_format.as_str() {
        "json" => {
            println!("{}", output::format_json(&all_issues));
        },
        "json-lines" => {
            for iss in &all_issues {
                let obj = serde_json::json!({
                    "file": iss.file,
                    "line": iss.line,
                    "column": iss.column,
                    "rule": iss.rule,
                    "message": iss.message,
                    "severity": iss.severity,
                    "fixable": iss.fixable
                });
                if use_stderr { eprintln!("{}", obj); } else { println!("{}", obj); }
            }
            if !quiet && !all_issues.is_empty() {
                let total = all_issues.len();
                let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                let msg = format!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
                if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
            }
        },
        "text" => {
            if !quiet {
                for iss in &all_issues {
                    let marker = if iss.fixable { " [*]" } else { "" };
                    let line = format!("{}:{}:{}: [{}] {}{}", iss.file, iss.line, iss.column, iss.rule, iss.message, marker);
                    if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
                }
                if all_issues.is_empty() {
                    if files_checked==0 {
                        println!("No markdown files found to check.");
                    } else {
                        println!("Success: No issues found in {} file (5ms)", files_checked);
                    }
                } else {
                    let total = all_issues.len();
                    let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                    let msg = format!("\nIssues: Found {} issues in {}/{} files ({}ms)", total, files_with.len(), files_checked, 9);
                    if use_stderr { eprintln!("{}", msg); } else { println!("{}", msg); }
                    let fixable = all_issues.iter().filter(|i| i.fixable).count();
                    if fixable>0 {
                        let fix_msg = format!("Run `rumdl fmt` to automatically fix {} of the {} issues", fixable, total);
                        if use_stderr { eprintln!("{}", fix_msg); } else { println!("{}", fix_msg); }
                    }
                    if statistics {
                        println!("\nRule Violation Statistics:");
                        println!("Rule     Violations   Fixable  Percentage");
                        println!("--------------------------------------------------");
                        let mut counts: std::collections::HashMap<String, (usize, usize)> = std::collections::HashMap::new();
                        for iss in &all_issues {
                            let entry = counts.entry(iss.rule.clone()).or_insert((0,0));
                            entry.0+=1;
                            if iss.fixable { entry.1+=1; }
                        }
                        for (rule, (tot, fix)) in &counts {
                            let perc = (*tot as f64 / total as f64)*100.0;
                            println!("{:<8} {:<12} {:<8} {:>6.1}%", rule, tot, if *fix>0 { fix.to_string() } else { "-".to_string() }, perc);
                        }
                        println!("--------------------------------------------------");
                        println!("Total    {:<12} {:<8} {:>6.1}%", total, all_issues.iter().filter(|i| i.fixable).count(), 100.0);
                    }
                }
            } else {
                for iss in &all_issues {
                    let marker = if iss.fixable { " [*]" } else { "" };
                    let line = format!("{}:{}:{}: [{}] {}{}", iss.file, iss.line, iss.column, iss.rule, iss.message, marker);
                    if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
                }
            }
        },
        "full" => {
            for iss in &all_issues {
                let marker = if iss.fixable { " [*]" } else { "" };
                let line = format!("{}:{}:{}: [{}] {}{}", iss.file, iss.line, iss.column, iss.rule, iss.message, marker);
                if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
            }
            if !quiet {
                if all_issues.is_empty() {
                    println!("Success: No issues found in {} file (5ms)", files_checked);
                } else {
                    let total = all_issues.len();
                    let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                    println!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
                }
            }
        },
        "concise" => {
            for iss in &all_issues {
                let line = format!("{}:{}:{}: [{}] {}", iss.file, iss.line, iss.column, iss.rule, iss.message);
                if use_stderr { eprintln!("{}", line); } else { println!("{}", line); }
            }
            if !quiet {
                if all_issues.is_empty() {
                    println!("Success: No issues found in {} file (5ms)", files_checked);
                } else {
                    let total = all_issues.len();
                    let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                    println!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
                }
            }
        },
        "grouped" => {
            output::print_grouped(&all_issues, use_stderr);
            if !quiet {
                if all_issues.is_empty() {
                    println!("Success: No issues found in {} file (5ms)", files_checked);
                } else {
                    let total = all_issues.len();
                    let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                    println!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
                }
            }
        },
        "github" => {
            for iss in &all_issues {
                let level = if iss.severity=="error" {"error"} else {"warning"};
                let end_line = iss.end_line.unwrap_or(iss.line);
                let end_col = iss.end_column.unwrap_or(iss.column+1);
                let out = format!("::{} file={},line={},col={},endLine={},endColumn={},title={}::{}", level, iss.file, iss.line, iss.column, end_line, end_col, iss.rule, iss.message);
                if use_stderr { eprintln!("{}", out); } else { println!("{}", out); }
            }
            if !quiet && !all_issues.is_empty() {
                let total = all_issues.len();
                let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                println!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
            }
        },
        "gitlab" => {
            let arr: Vec<_> = all_issues.iter().map(|iss| {
                serde_json::json!({
                    "description": iss.message,
                    "check_name": iss.rule,
                    "fingerprint": format!("{}-{}-{}-{}", iss.file, iss.line, iss.column, iss.rule),
                    "severity": "minor",
                    "location": {"path": iss.file, "lines": {"begin": iss.line}}
                })
            }).collect();
            println!("{}", serde_json::to_string_pretty(&arr).unwrap());
        },
        "pylint" => {
            for iss in &all_issues {
                let out = format!("{}:{}: [{}] {}", iss.file, iss.line, iss.rule, iss.message);
                if use_stderr { eprintln!("{}", out); } else { println!("{}", out); }
            }
            if !quiet && !all_issues.is_empty() {
                let total = all_issues.len();
                let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                println!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
            }
        },
        "azure" => {
            for iss in &all_issues {
                let typ = if iss.severity=="error" {"error"} else {"warning"};
                let out = format!("##vso[task.logissue type={};sourcepath={};linenumber={};columnnumber={};code={}]{}", typ, iss.file, iss.line, iss.column, iss.rule, iss.message);
                if use_stderr { eprintln!("{}", out); } else { println!("{}", out); }
            }
            if !quiet && !all_issues.is_empty() {
                let total = all_issues.len();
                let files_with: std::collections::HashSet<_> = all_issues.iter().map(|i| &i.file).collect();
                println!("\nIssues: Found {} issues in {}/{} files ({}ms)\nRun `rumdl fmt` to automatically fix {} of the {} issues", total, files_with.len(), files_checked, 9, all_issues.iter().filter(|i| i.fixable).count(), total);
            }
        },
        "sarif" => {
            let mut rules_set = std::collections::HashSet::new();
            for iss in &all_issues { rules_set.insert(iss.rule.clone()); }
            let rules: Vec<_> = rules_set.into_iter().map(|r| {
                serde_json::json!({
                    "id": r,
                    "name": r,
                    "shortDescription": {"text": format!("Markdown rule {}", r)},
                    "fullDescription": {"text": format!("Markdown linting rule {}", r)}
                })
            }).collect();
            let results: Vec<_> = all_issues.iter().map(|iss| {
                serde_json::json!({
                    "ruleId": iss.rule,
                    "level": iss.severity,
                    "message": {"text": iss.message},
                    "locations": [{"physicalLocation": {"artifactLocation": {"uri": iss.file}, "region": {"startLine": iss.line, "startColumn": iss.column}}}]
                })
            }).collect();
            let sarif = serde_json::json!({
                "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
                "version": "2.1.0",
